template <typename T>
class DataPoint {
private:
    T val;
public:
    DataPoint(T v) : val(v) {}

    // Required template declaration for friend function
    template <typename U>
    friend bool operator<=(const DataPoint<U>& a,
                           const DataPoint<U>& b);
};

// Operator overloading defined externally as a function template
template <typename T>
bool operator<=(const DataPoint<T>& a,
                const DataPoint<T>& b) {
    return a.val <= b.val;
}
